613	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
614	    @Override
615	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
616	        Owner owner = this.clinicService.findOwnerById(ownerId);
617	        if (owner == null) {
618	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
619	        }
620	        owner.setHouseholdSize(householdSize(owner));
621	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
622	        ownerDto.setMembershipLevel(cappedMembershipLevel(owner));
623	        ownerDto.setBulkSignupWarning(owner.getRegistrationDate() != null
624	            && ownersCreatedOn(owner.getRegistrationDate()) > 80);
625	        ownerDto.setCapacityWarning(capacityWarning(owner.getCity()));
