630	    /**
631	     * The value of the {@code Idempotency-Key} header on the current request, or {@code null} when the
632	     * request carries no such header (or there is no active servlet request). A blank value is treated
633	     * as absent.
634	     */
635	    private static String currentIdempotencyKey() {
636	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
637	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
638	            return null;
639	        }
640	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
641	        return (key == null || key.isBlank()) ? null : key;
