644	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
645	    @Override
646	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
647	        String idempotencyKey = currentIdempotencyKey();
648	        if (idempotencyKey != null) {
649	            Integer existingId = this.idempotentCreations.get(idempotencyKey);
650	            if (existingId != null) {
651	                Owner existing = this.clinicService.findOwnerById(existingId);
652	                if (existing != null) {
653	                    existing.setHouseholdSize(householdSize(existing));
654	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
655	                    existingDto.setMembershipLevel(cappedMembershipLevel(existing));
656	                    existingDto.setBulkSignupWarning(existing.getRegistrationDate() != null
657	                        && ownersCreatedOn(existing.getRegistrationDate()) > 80);
658	                    existingDto.setCapacityWarning(capacityWarning(existing.getCity()));
659	                    existingDto.setRiskFlag(riskFlag(existing));
660	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
661	                }
662	            }
663	        }
664	        String telephone = toE164(ownerFieldsDto.getTelephone());
665	        if (telephone == null) {
666	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
667	        }
668	        String email = ownerFieldsDto.getEmail();
669	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
670	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
671	        }
672	        if (isDisposableEmailDomain(email)) {
673	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
674	        }
675	        // Structured address is preferred when supplied (a non-blank 'addressLine1'); otherwise the
676	        // flat 'address' input is used for backward compatibility. Normalization applies to whichever
677	        // fields are supplied, and the composed 'address' is the normalized addressLine1 with the
678	        // normalized addressLine2 appended after a single space when present.
679	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
680	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
681	        boolean structuredAddress = !addressLine1.isEmpty();
682	        String address;
683	        if (structuredAddress) {
684	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
685	        } else {
686	            address = normaliseAddress(ownerFieldsDto.getAddress());
687	        }
688	        if (address.isEmpty()) {
689	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
690	        }
691	        String postcode = ownerFieldsDto.getPostcode();
692	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
693	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
694	        }
695	        if (ownerFieldsDto.getRegistrationDate() != null
696	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
697	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
698	        }
699	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
700	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
701	        LocalDate registrationDate = toBusinessDay(effectiveDate);
702	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
703	            .map(Owner::getRegistrationDate)
704	            .filter(existing -> existing != null)
705	            .map(OwnerRestControllerV1::toBusinessDay)
706	            .filter(registrationDate::equals)
707	            .count();
